CRK.SHEET_LOOK = { br: .015, depth: 1, kink: .2, hold: .6, depthK: .38, web: 1, rootW: .9, webLit: .3, chipK: 1.9, inkK: .75, chipHole: .7 };
CRK.SHEET_CHUNK = Object.assign({}, CRK.SHEET_LOOK, { rootW: 1, kink: .3, hold: .45 });
CRK.SHEET_SPOTS = (F, lh, k) => [
  Object.assign({ id: 'fLL', at: [F.x + 2, F.y + F.h - 52 * k], dir: -.5, len: 120, w: 24, holes: [[.2, 1.7, 30]], seed: 701, zone: [F.x + 1, F.y + F.h - 200 * k, F.x + 150 * k, F.y + F.h - 3], mat: 'sheet', rest: .74, minLen: 50 }, CRK.SHEET_CHUNK),
  Object.assign({ id: 'fLR', at: [F.x + F.w - 2, F.y + F.h - 70 * k], dir: Math.PI + .55, len: 120, w: 24, holes: [[.2, 1.7, 30]], seed: 702, zone: [F.x + F.w - 150 * k, F.y + F.h - 200 * k, F.x + F.w - 1, F.y + F.h - 3], mat: 'sheet', rest: .74, minLen: 50 }, CRK.SHEET_CHUNK),
  Object.assign({ id: 'fUL', at: [F.x + 2, F.y + lh + 46 * k], dir: .35, len: 100, w: 19, holes: [[.22, 1.6, 24]], seed: 703, zone: [F.x + 1, F.y + lh + 6, F.x + 56 * k, F.y + lh + 270 * k], mat: 'sheet', rest: .74, minLen: 50 }, CRK.SHEET_CHUNK),
  Object.assign({ id: 'fUR', at: [F.x + F.w - 2, F.y + lh + 90 * k], dir: Math.PI - .35, len: 100, w: 19, holes: [[.22, 1.6, 24]], seed: 704, zone: [F.x + F.w - 56 * k, F.y + lh + 6, F.x + F.w - 1, F.y + lh + 270 * k], mat: 'sheet', rest: .74, minLen: 50 }, CRK.SHEET_CHUNK),
  // the side fractures run DOWN the frame's side border (they break the gold and the inner rule)
  Object.assign({ id: 'fSL', at: [F.x + 7, F.y + lh + 34 * k], dir: Math.PI / 2 + .1, len: 330, w: 17, holes: [[.28, 1.6, 24], [.66, 1.45, 20]], seed: 705, zone: [F.x - 5, F.y + lh + 14, F.x + 34 * k, F.y + F.h - 26 * k], mat: 'sheet', rest: .72, minLen: 60 }, CRK.SHEET_LOOK, { rootW: .7 }),
  Object.assign({ id: 'fSR', at: [F.x + F.w - 7, F.y + lh + 70 * k], dir: Math.PI / 2 - .1, len: 300, w: 17, holes: [[.28, 1.6, 24], [.66, 1.45, 20]], seed: 706, zone: [F.x + F.w - 34 * k, F.y + lh + 14, F.x + F.w + 5, F.y + F.h - 26 * k], mat: 'sheet', rest: .72, minLen: 60 }, CRK.SHEET_LOOK, { rootW: .7 }),
  // into the header band beside the title (sky tones)
  Object.assign({ id: 'fHL', at: [F.x + 3, F.y + lh - 34 * k], dir: .3, len: 100, w: 19, holes: [[.22, 1.6, 24]], seed: 707, zone: [F.x - 3, F.y + 58 * k, F.x + 128 * k, F.y + lh - 4], mat: 'sheetSky', rest: .76, minLen: 50 }, CRK.SHEET_CHUNK),
  Object.assign({ id: 'fHR', at: [F.x + F.w - 3, F.y + lh - 52 * k], dir: Math.PI - .3, len: 100, w: 19, holes: [[.22, 1.6, 24]], seed: 708, zone: [F.x + F.w - 128 * k, F.y + 58 * k, F.x + F.w + 3, F.y + lh - 4], mat: 'sheetSky', rest: .76, minLen: 50 }, CRK.SHEET_CHUNK)
];
